import { observer } from 'mobx-react-lite';
import React, { useEffect, useState } from 'react';
import { useLocation, useParams} from 'react-router-dom/cjs/react-router-dom';
import { useContext } from 'react';
import { Context } from '../index';
import { getBasket , delFromBasket} from '../http/basketAPI';
import { Button, Card, Col, Container, Row, Spinner } from 'react-bootstrap'
import { getOneOrder, getOneOrderInfo } from '../http/orderAPI';

const OrderPage = () => {
  const {order} = useContext(Context)
  const id = useParams()
  const [loading, setLoading] = useState(true)

  function stop(){
    setLoading(false)
  }

  useEffect(() =>{
    getOneOrder(id.id).then(data => order.setOneOrder(data)).finally(setTimeout(stop, 1000))
    getOneOrderInfo(id.id).then(data => order.setDishes(data)).finally(setTimeout(stop, 1000))
  }, [])

  if (loading){
    return <Spinner animation={"grow"}/>
  }

  return (
    <Container className="min-vh-100 d-flex flex-sm-column mt-3">
      <h3>Замовлення №{id.id}</h3>
      <div>Ім'я: {order.oneOrder.name}</div>
      <div>Телефон: {order.oneOrder.phone}</div>
      <div>Адреса доставки: {order.oneOrder.address}</div>
      <div>Тип оплати: {order.oneOrder.paytype}</div>

    </Container>
  );
};

export default OrderPage;
